5.2 Subzone coverage check: how many subzones have ≥1 registration (by sector)

# all sector × subzone combinations in your study window
all_grid &lt;- expand_grid(
  sector    = unique(biz_pts_use$sector),
  SUBZONE_N = unique(subzones_use$SUBZONE_N)
)

# fill missing combos with n = 0, then compute has_any
subzone_cover &lt;- biz_pts_use |&gt;
  st_drop_geometry() |&gt;
  count(sector, SUBZONE_N, name = "n") |&gt;
  right_join(all_grid, by = c("sector","SUBZONE_N")) |&gt;
  mutate(n = replace_na(n, 0), has_any = n &gt; 0) |&gt;
  count(sector, has_any, name = "subzones") |&gt;
  tidyr::pivot_wider(names_from = has_any, values_from = subzones, values_fill = 0) |&gt;
  rename(`subzones_with_≥1` = `TRUE`, `subzones_with_0` = `FALSE`) |&gt;
  mutate(subzones_total = `subzones_with_≥1` + `subzones_with_0`) |&gt;
  select(sector, subzones_total, `subzones_with_≥1`, `subzones_with_0`) |&gt;
  arrange(sector)

